sys_ux_data_broker_transform.output_schema:
{
 "html": "Carmen Man has a limited travel history with only 1 duty travel request raised on 20 Jul 2025. Based on this single request, it is not possible to identify a clear pattern in their preferences for ports of destination or cabin classes. However, it can be observed that Carmen prefers travel to Singapore, (SIN) for Southeast Asian destinations based on the single duty request raised on 20 Jul 2025. They also have a preference to travel by Economy class based on the single duty travel request submitted on 20 Jul 2025.",
 "updatedOn": "2025-07-07 01:08:34"
}

sys_ux_data_broker_transform.script:
function transform(input) {
	var sysId = input.sysId;
	var table = input.table;

	//var result = {};

	let summaryResultHTML = "";

	var request = {
		executionRequests: [{
			payload: {
				duty_travel_request: {
					tableName: table,
					sysId: sysId,
					queryString: ''
				}
			},
			capabilityId: '1f36b94e473ae690873506f1d16d432b',
			meta: {
				skillConfigId: 'a736f18e473ae690873506f1d16d43a5'
			}
		}],
		mode: 'sync'
	};

	try {
		var output = sn_one_extend.OneExtendUtil.execute(request)['capabilities'][request.executionRequests[0].capabilityId]['response'];
		var resultHTML = JSON.parse(output).model_output;

		let lines = resultHTML.split('\n');
		summaryResultHTML = lines.map(line => {
		if (line.includes(':')) {
			let [label, ...rest] = line.split(':');
			return `<p><b>${label}:</b>${rest.join(':')}</p>`;
		}
		return `<p>${line}</p>`;
		}).join('');
	} catch (e) {
		gs.error(e);
		summaryResultHTML = 'Something went wrong while executing the skill.';
	}

	return {
		html: summaryResultHTML,
		updatedOn: new GlideDateTime().getDisplayValue()
	};
}
